163→/// Truncate a string to max_len chars, appending "..." if truncated.
164→fn truncate_str(s: &str, max_len: usize) -> &str {
165→    if s.len() <= max_len {
166→        s
167→    } else {
168→        // Find a safe char boundary
169→        let mut end = max_len;
170→        while end > 0 && !s.is_char_boundary(end) {
171→            end -= 1;
172→        }
173→        &s[..end]
174→    }
175→}
