177→/// Summarize a JSON tool input to a brief string.
178→fn summarize_json_input(input: &serde_json::Value) -> String {
179→    match input {
180→        serde_json::Value::Object(map) => {
181→            let keys: Vec<&String> = map.keys().take(3).collect();
182→            if keys.is_empty() {
183→                "{}".to_string()
184→            } else {
185→                let pairs: Vec<String> = keys
186→                    .iter()
187→                    .map(|k| {
188→                        let v = &map[*k];
189→                        let v_str = match v {
190→                            serde_json::Value::String(s) => truncate_str(s, 60).to_string(),
191→                            _ => {
192→                                let s = v.to_string();
193→                                truncate_str(&s, 60).to_string()
194→                            }
195→                        };
196→                        format!("{k}={v_str}")
197→                    })
198→                    .collect();
199→                pairs.join(", ")
200→            }
201→        }
202→        serde_json::Value::String(s) => truncate_str(s, 100).to_string(),
203→        other => {
204→            let s = other.to_string();
205→            truncate_str(&s, 100).to_string()
206→        }
207→    }
208→}
