210→/// Call the Anthropic Messages API.
211→fn call_claude(api_key: &str, model: &str, user_message: &str) -> Result<String, CaptureError> {
212→    let client = reqwest::blocking::Client::builder()
213→        .timeout(std::time::Duration::from_secs(TIMEOUT_SECS))
214→        .build()
215→        .map_err(|e| CaptureError::LlmError(format!("HTTP client error: {e}")))?;
216→
217→    let body = serde_json::json!({
218→        "model": model,
219→        "max_tokens": MAX_TOKENS,
220→        "system": SYSTEM_PROMPT,
221→        "messages": [
222→            { "role": "user", "content": user_message }
223→        ]
224→    });
225→
226→    let response = client
227→        .post(API_URL)
228→        .header("x-api-key", api_key)
229→        .header("anthropic-version", API_VERSION)
230→        .header("content-type", "application/json")
231→        .json(&body)
232→        .send()
233→        .map_err(|e| CaptureError::LlmError(format!("API request failed: {e}")))?;
234→
235→    if !response.status().is_success() {
236→        let status = response.status();
237→        let body_text = response.text().unwrap_or_default();
238→        return Err(CaptureError::LlmError(format!(
239→            "API returned {status}: {body_text}"
240→        )));
241→    }
242→
243→    let resp_json: serde_json::Value = response
244→        .json()
245→        .map_err(|e| CaptureError::LlmError(format!("Failed to parse API response: {e}")))?;
246→
247→    // Extract text from the first content block
248→    resp_json["content"]
249→        .as_array()
250→        .and_then(|arr| arr.first())
251→        .and_then(|block| block["text"].as_str())
252→        .map(|s| s.to_string())
253→        .ok_or_else(|| CaptureError::LlmError("No text in API response".to_string()))
254→}
255→
256→/// Response from LLM summarization.
257→struct SummarizeResponse {
258→    summary: Option<String>,
259→    interpreted_goal: Option<String>,
260→    dead_ends: Vec<DeadEnd>,
261→    decisions: Vec<Decision>,
262→}
263→
264→/// Parse the LLM JSON response into structured fields.
265→fn parse_response(text: &str) -> Result<SummarizeResponse, CaptureError> {
266→    // Strip markdown code fencing if present
267→    let cleaned = text
268→        .trim()
269→        .strip_prefix("```json")
270→        .or_else(|| text.trim().strip_prefix("```"))
271→        .unwrap_or(text.trim());
272→    let cleaned = cleaned.strip_suffix("```").unwrap_or(cleaned).trim();
273→
274→    let json: serde_json::Value = serde_json::from_str(cleaned)
275→        .map_err(|e| CaptureError::LlmError(format!("Invalid JSON from LLM: {e}")))?;
276→
277→    let summary = json["summary"].as_str().map(|s| s.to_string());
278→    let interpreted_goal = json["interpreted_goal"].as_str().map(|s| s.to_string());
279→
280→    let dead_ends = json["dead_ends"]
281→        .as_array()
282→        .map(|arr| {
283→            arr.iter()
284→                .filter_map(|de| {
285→                    Some(DeadEnd {
286→                        approach: de["approach"].as_str()?.to_string(),
287→                        reason: de["reason"].as_str()?.to_string(),
288→                    })
289→                })
290→                .collect()
291→        })
292→        .unwrap_or_default();
293→
294→    let decisions = json["decisions"]
295→        .as_array()
296→        .map(|arr| {
297→            arr.iter()
298→                .filter_map(|d| {
299→                    Some(Decision {
300→                        description: d["description"].as_str()?.to_string(),
301→                        rationale: d["rationale"].as_str()?.to_string(),
302→                    })
303→                })
304→                .collect()
305→        })
306→        .unwrap_or_default();
307→
308→    Ok(SummarizeResponse {
309→        summary,
310→        interpreted_goal,
311→        dead_ends,
312→        decisions,
313→    })
314→}
315→
316→/// Apply LLM-generated fields to the EngramData.
317→fn apply_response(data: &mut EngramData, response: &SummarizeResponse) {
318→    if let Some(summary) = &response.summary {
319→        data.manifest.summary = Some(summary.clone());
320→        data.intent.summary = Some(summary.clone());
321→    }
322→    if let Some(goal) = &response.interpreted_goal {
323→        data.intent.interpreted_goal = Some(goal.clone());
324→    }
325→    if !response.dead_ends.is_empty() {
326→        data.intent.dead_ends = response.dead_ends.clone();
327→    }
328→    if !response.decisions.is_empty() {
329→        data.intent.decisions = response.decisions.clone();
330→    }
331→}
