  2→
  3→/// Best-effort extraction of reasoning insights from raw PTY output.
  4→///
  5→/// This is heuristic: it looks for common phrases that indicate rejected
  6→/// approaches or architectural decisions. Returns empty vecs if no patterns found.
  7→pub fn extract_insights(raw_output: &[u8]) -> ExtractedInsights {
  8→    let text = String::from_utf8_lossy(raw_output);
  9→    let mut dead_ends = Vec::new();
 10→    let mut decisions = Vec::new();
 11→
 12→    for line in text.lines() {
 13→        let trimmed = line.trim();
 14→        if trimmed.is_empty() || trimmed.len() < 10 {
 15→            continue;
 16→        }
 17→        // Skip lines that look like markdown formatting, code, or structured content
 18→        if trimmed.starts_with('#')
 19→            || trimmed.starts_with('|')
 20→            || trimmed.starts_with("```")
 21→            || trimmed.starts_with("- **")
 22→            || trimmed.starts_with("**")
 23→            || trimmed.contains("](")
 24→        {
 25→            continue;
 26→        }
 27→        let lower = trimmed.to_lowercase();
 28→
 29→        // Dead end patterns
 30→        if let Some(de) = try_extract_dead_end(&lower, trimmed) {
 31→            dead_ends.push(de);
 32→        }
 33→
 34→        // Decision patterns
 35→        if let Some(d) = try_extract_decision(&lower, trimmed) {
 36→            decisions.push(d);
 37→        }
 38→    }
 39→
 40→    // Deduplicate by approach/description
 41→    dead_ends.dedup_by(|a, b| a.approach == b.approach);
 42→    decisions.dedup_by(|a, b| a.description == b.description);
 43→
 44→    ExtractedInsights {
 45→        dead_ends,
 46→        decisions,
 47→    }
 48→}
 49→
 50→pub struct ExtractedInsights {
 51→    pub dead_ends: Vec<DeadEnd>,
 52→    pub decisions: Vec<Decision>,
 53→}
 54→
 55→fn try_extract_dead_end(lower: &str, original: &str) -> Option<DeadEnd> {
 56→    // Pattern: "tried X but Y"
 57→    if let Some(rest) = lower.strip_prefix("tried ") {
 58→        if let Some((approach, reason)) = rest.split_once(" but ") {
 59→            return Some(DeadEnd {
 60→                approach: approach.trim().to_string(),
 61→                reason: reason.trim().to_string(),
 62→            });
 63→        }
 64→    }
 65→
 66→    // Pattern: "rejected X because Y" or "rejected X: Y"
 67→    if let Some(rest) = lower.strip_prefix("rejected ") {
 68→        if let Some((approach, reason)) = rest
 69→            .split_once(" because ")
 70→            .or_else(|| rest.split_once(": "))
 71→        {
 72→            return Some(DeadEnd {
 73→                approach: approach.trim().to_string(),
 74→                reason: reason.trim().to_string(),
 75→            });
 76→        }
 77→    }
 78→
 79→    // Pattern: "X didn't work because Y" (short lines only to avoid matching prose)
 80→    if original.len() < 120 {
 81→        if let Some(pos) = lower.find(" didn't work") {
 82→            let approach = &original[..pos];
 83→            let reason = lower
 84→                .get((pos + " didn't work".len())..)
 85→                .and_then(|r| r.strip_prefix(" because ").or(r.strip_prefix(": ")))
 86→                .unwrap_or("did not work as expected");
 87→            if !approach.is_empty() && approach.len() < 80 {
 88→                return Some(DeadEnd {
 89→                    approach: approach.trim().to_string(),
 90→                    reason: reason.trim().to_string(),
 91→                });
 92→            }
 93→        }
 94→    }
 95→
 96→    // Pattern: "instead of X" (looser, only if line is short enough to be a summary)
 97→    if lower.contains("instead of ") && original.len() < 120 {
 98→        if let Some(pos) = lower.find("instead of ") {
 99→            let approach = &original[(pos + "instead of ".len())..];
100→            let reason = &original[..pos];
101→            if !approach.is_empty() && approach.len() < 80 && !reason.is_empty() {
102→                return Some(DeadEnd {
103→                    approach: approach.trim().trim_end_matches('.').to_string(),
104→                    reason: reason.trim().to_string(),
105→                });
106→            }
107→        }
108→    }
109→
110→    None
111→}
112→
113→fn try_extract_decision(lower: &str, original: &str) -> Option<Decision> {
114→    // Pattern: "decided to X because Y"
115→    if let Some(rest) = lower.strip_prefix("decided to ") {
116→        if let Some((desc, rationale)) = rest.split_once(" because ") {
117→            return Some(Decision {
118→                description: desc.trim().to_string(),
119→                rationale: rationale.trim().to_string(),
120→            });
121→        }
122→    }
123→
124→    // Pattern: "chose X over Y" (short lines only)
125→    if lower.starts_with("chose ") && original.len() < 120 {
126→        if let Some((desc, _)) = lower
127→            .strip_prefix("chose ")
128→            .and_then(|r| r.split_once(" over "))
129→        {
130→            return Some(Decision {
131→                description: desc.trim().to_string(),
132→                rationale: original.to_string(),
133→            });
134→        }
135→    }
136→
137→    None
138→}
