421→/// Convert a filesystem path to Claude Code's project key format.
422→/// /Users/sjonas/myproject -> -Users-sjonas-myproject
423→fn path_to_claude_key(path: &Path) -> String {
424→    let s = path.to_string_lossy();
425→    let s = s.trim_end_matches('/');
426→    s.replace('/', "-")
427→}
