  8→/// Handle the `prepare-commit-msg` hook.
  9→///
 10→/// If an active engram session exists, appends Engram trailers to the commit message.
 11→pub fn handle_prepare_commit_msg(msg_file: &Path, git_dir: &Path) -> Result<(), CoreError> {
 12→    let session = match ActiveSession::load(git_dir) {
 13→        Some(s) => s,
 14→        None => return Ok(()), // No active session, nothing to do
 15→    };
 16→
 17→    let mut msg = fs::read_to_string(msg_file)?;
 18→
 19→    // Don't add trailers if they're already there
 20→    if msg.contains("Engram-Id:") {
 21→        return Ok(());
 22→    }
 23→
 24→    // Ensure blank line before trailers
 25→    if !msg.ends_with('\n') {
 26→        msg.push('\n');
 27→    }
 28→    msg.push('\n');
 29→
 30→    msg.push_str(&format!("Engram-Id: {}\n", session.engram_id.as_str()));
 31→    msg.push_str(&format!(
 32→        "Engram-Agent: {}{}\n",
 33→        session.agent.name,
 34→        session
 35→            .agent
 36→            .model
 37→            .as_ref()
 38→            .map(|m| format!("/{m}"))
 39→            .unwrap_or_default()
 40→    ));
 41→    if let Some(model) = &session.agent.model {
 42→        msg.push_str(&format!("Engram-Model: {model}\n"));
 43→    }
 44→    msg.push_str(&format!(
 45→        "Engram-Tokens: {}\n",
 46→        session.token_usage.total_tokens
 47→    ));
 48→    if let Some(cost) = session
 49→        .token_usage
 50→        .effective_cost(session.agent.model.as_deref())
 51→    {
 52→        msg.push_str(&format!("Engram-Cost: ${cost:.2}\n"));
 53→    }
 54→
 55→    fs::write(msg_file, msg)?;
 56→    Ok(())
 57→}
