 59→/// Handle the `post-commit` hook.
 60→///
 61→/// If an active engram session exists, records the new commit SHA.
 62→pub fn handle_post_commit(git_dir: &Path) -> Result<(), CoreError> {
 63→    let mut session = match ActiveSession::load(git_dir) {
 64→        Some(s) => s,
 65→        None => return Ok(()),
 66→    };
 67→
 68→    // Read HEAD to get the new commit SHA
 69→    let repo = git2::Repository::open(git_dir.parent().unwrap_or(git_dir))?;
 70→    let head = repo.head()?;
 71→    let sha = head.target().map(|oid| oid.to_string()).unwrap_or_default();
 72→
 73→    if !sha.is_empty() {
 74→        session.add_commit(&sha, git_dir)?;
 75→    }
 76→
 77→    Ok(())
 78→}
