  1→use std::path::Path;
  2→
  3→use crate::error::CoreError;
  4→
  5→const ENGRAM_HOOK_MARKER: &str = "hook-handler session-end";
  6→
  7→/// Install a Claude Code `SessionEnd` hook that auto-imports sessions.
  8→///
  9→/// Creates or updates `.claude/settings.json` in the project root.
 10→/// Idempotent: will not duplicate the hook if already present.
 11→pub fn install_claude_code_hook(project_root: &Path) -> Result<(), CoreError> {
 12→    let claude_dir = project_root.join(".claude");
 13→    std::fs::create_dir_all(&claude_dir)?;
 14→
 15→    let settings_path = claude_dir.join("settings.json");
 16→
 17→    // Read existing settings or start with empty object
 18→    let mut settings: serde_json::Value = if settings_path.exists() {
 19→        let content = std::fs::read_to_string(&settings_path)?;
 20→        if content.trim().is_empty() {
 21→            serde_json::json!({})
 22→        } else {
 23→            serde_json::from_str(&content).map_err(|e| {
 24→                CoreError::Config(format!("Failed to parse .claude/settings.json: {e}"))
 25→            })?
 26→        }
 27→    } else {
 28→        serde_json::json!({})
 29→    };
 30→
 31→    // Check if our hook already exists
 32→    if let Some(hooks) = settings.get("hooks") {
 33→        if let Some(session_end) = hooks.get("SessionEnd") {
 34→            let content = serde_json::to_string(session_end).unwrap_or_default();
 35→            if content.contains(ENGRAM_HOOK_MARKER) {
 36→                return Ok(());
 37→            }
 38→        }
 39→    }
 40→
 41→    // Resolve the engram binary path
 42→    let engram_path = std::env::current_exe()
 43→        .map(|p| p.to_string_lossy().to_string())
 44→        .unwrap_or_else(|_| "engram".to_string());
 45→
 46→    let hook_command = format!("{engram_path} hook-handler session-end");
 47→
 48→    // Build the hook entry
 49→    let hook_entry = serde_json::json!({
 50→        "matcher": "",
 51→        "hooks": [
 52→            {
 53→                "type": "command",
 54→                "command": hook_command
 55→            }
 56→        ]
 57→    });
 58→
 59→    // Merge into existing settings
 60→    let hooks_obj = settings
 61→        .as_object_mut()
 62→        .ok_or_else(|| CoreError::Config("settings.json is not a JSON object".into()))?
 63→        .entry("hooks")
 64→        .or_insert_with(|| serde_json::json!({}));
 65→
 66→    let session_end_arr = hooks_obj
 67→        .as_object_mut()
 68→        .ok_or_else(|| CoreError::Config("hooks is not a JSON object".into()))?
 69→        .entry("SessionEnd")
 70→        .or_insert_with(|| serde_json::json!([]));
 71→
 72→    session_end_arr
 73→        .as_array_mut()
 74→        .ok_or_else(|| CoreError::Config("SessionEnd is not an array".into()))?
 75→        .push(hook_entry);
 76→
 77→    // Write back with pretty formatting
 78→    let output = serde_json::to_string_pretty(&settings)
 79→        .map_err(|e| CoreError::Config(format!("Failed to serialize settings: {e}")))?;
 80→    std::fs::write(&settings_path, output)?;
 81→
 82→    Ok(())
 83→}
 84→
 85→/// Remove the Claude Code `SessionEnd` hook for engram.
 86→///
 87→/// Preserves all other settings and hooks.
 88→pub fn uninstall_claude_code_hook(project_root: &Path) -> Result<(), CoreError> {
 89→    let settings_path = project_root.join(".claude").join("settings.json");
 90→    if !settings_path.exists() {
 91→        return Ok(());
 92→    }
 93→
 94→    let content = std::fs::read_to_string(&settings_path)?;
 95→    let mut settings: serde_json::Value = serde_json::from_str(&content)
 96→        .map_err(|e| CoreError::Config(format!("Failed to parse settings: {e}")))?;
 97→
 98→    if let Some(hooks) = settings.get_mut("hooks") {
 99→        if let Some(session_end) = hooks.get_mut("SessionEnd") {
100→            if let Some(arr) = session_end.as_array_mut() {
101→                arr.retain(|entry| {
102→                    let s = serde_json::to_string(entry).unwrap_or_default();
103→                    !s.contains(ENGRAM_HOOK_MARKER)
104→                });
105→            }
106→        }
107→    }
108→
109→    let output = serde_json::to_string_pretty(&settings)
110→        .map_err(|e| CoreError::Config(format!("Failed to serialize settings: {e}")))?;
111→    std::fs::write(&settings_path, output)?;
112→
113→    Ok(())
114→}
