 15→#[derive(Args)]
 16→pub struct HookHandlerArgs {
 17→    /// The hook name (prepare-commit-msg, post-commit, pre-push)
 18→    pub hook_name: String,
 19→
 20→    /// Extra arguments passed by git to the hook
 21→    #[arg(trailing_var_arg = true)]
 22→    pub args: Vec<String>,
 23→}
 24→
 25→pub fn run(args: &HookHandlerArgs) -> Result<()> {
 26→    // Find the git dir by discovering the repo
 27→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 28→    let git_dir = storage.repo().path().to_path_buf();
 29→
 30→    match args.hook_name.as_str() {
 31→        "prepare-commit-msg" => {
 32→            // Auto-capture: if enabled and no active session, import current Claude Code session
 33→            maybe_auto_capture(&storage, &git_dir);
 34→
 35→            let msg_file = args
 36→                .args
 37→                .first()
 38→                .map(PathBuf::from)
 39→                .context("prepare-commit-msg: missing message file argument")?;
 40→            hooks::handle_prepare_commit_msg(&msg_file, &git_dir)?;
 41→        }
 42→        "post-commit" => {
 43→            hooks::handle_post_commit(&git_dir)?;
 44→
 45→            // Auto-capture cleanup: if session was auto-created, clean it up
 46→            maybe_auto_capture_cleanup(&storage, &git_dir);
 47→        }
 48→        "pre-push" => {
 49→            maybe_auto_push(&storage);
 50→        }
 51→        "session-end" => {
 52→            handle_session_end(&storage);
 53→        }
 54→        other => {
 55→            tracing::debug!("Unknown hook: {other}, ignoring");
 56→        }
 57→    }
 58→
 59→    Ok(())
 60→}
 61→
 62→/// Handle Claude Code's `SessionEnd` hook.
 63→///
 64→/// Reads JSON from stdin (provided by Claude Code), extracts the `transcript_path`,
 65→/// and imports the session as an engram. All errors are logged at debug level and
 66→/// silently ignored so we never interfere with the user's workflow.
 67→fn handle_session_end(storage: &GitStorage) {
 68→    let mut input = String::new();
 69→    if std::io::stdin().read_to_string(&mut input).is_err() {
 70→        tracing::debug!("session-end: failed to read stdin");
 71→        return;
 72→    }
 73→
 74→    let json: serde_json::Value = match serde_json::from_str(&input) {
 75→        Ok(v) => v,
 76→        Err(e) => {
 77→            tracing::debug!("session-end: failed to parse JSON: {e}");
 78→            return;
 79→        }
 80→    };
 81→
 82→    let transcript_path = match json.get("transcript_path").and_then(|v| v.as_str()) {
 83→        Some(p) => std::path::PathBuf::from(p),
 84→        None => {
 85→            tracing::debug!("session-end: no transcript_path in input");
 86→            return;
 87→        }
 88→    };
 89→
 90→    if !transcript_path.exists() {
 91→        tracing::debug!(
 92→            "session-end: transcript file does not exist: {}",
 93→            transcript_path.display()
 94→        );
 95→        return;
 96→    }
 97→
 98→    let mut data = match ClaudeCodeImporter::import_session(&transcript_path) {
 99→        Ok(d) => d,
100→        Err(e) => {
101→            tracing::debug!("session-end: failed to import session: {e}");
102→            return;
103→        }
104→    };
105→
106→    // Best-effort LLM summarization
107→    if let Err(e) = summarize_intent(&mut data) {
108→        tracing::debug!("session-end: LLM summarization failed: {e}");
109→    }
110→
111→    // Check for duplicates via source_hash
112→    if let Some(existing_id) = data
113→        .manifest
114→        .source_hash
115→        .as_deref()
116→        .and_then(|h| storage.find_by_source_hash(h))
117→    {
118→        tracing::debug!(
119→            "session-end: already imported as {}",
120→            &existing_id.as_str()[..8]
121→        );
122→        return;
123→    }
124→
125→    let id = data.manifest.id.clone();
126→    match storage.create(&data) {
127→        Ok(_) => {
128→            // Best-effort index update
129→            if let Ok(engine) = SearchEngine::open(storage) {
130→                let _ = engine.index_engram(&data);
131→            }
132→            tracing::debug!("session-end: imported engram {}", &id.as_str()[..8]);
133→
134→            // Best-effort: annotate commits that reference this engram
135→            auto_annotate_commits(storage, &data);
136→        }
137→        Err(e) => {
138→            tracing::debug!("session-end: failed to store engram: {e}");
139→        }
140→    }
141→}
142→
143→/// Scan recent commits for Engram-Id trailers matching the given engram,
144→/// and attach git notes with rich reasoning metadata.
145→fn auto_annotate_commits(storage: &GitStorage, data: &engram_core::model::EngramData) {
146→    use engram_core::notes::{format_note, ENGRAM_NOTES_REF};
147→
148→    let repo = storage.repo();
149→    let engram_id_str = data.manifest.id.as_str().to_string();
150→
151→    // Walk recent commits looking for Engram-Id trailers
152→    let head = match repo.head().and_then(|h| h.peel_to_commit()) {
153→        Ok(c) => c,
154→        Err(_) => return,
155→    };
156→
157→    let sig = repo
158→        .signature()
159→        .unwrap_or_else(|_| git2::Signature::now("engram", "engram@localhost").unwrap());
160→
161→    let mut revwalk = match repo.revwalk() {
162→        Ok(r) => r,
163→        Err(_) => return,
164→    };
165→    if revwalk.push(head.id()).is_err() {
166→        return;
167→    }
168→
169→    let note = format_note(data);
170→    let mut annotated = 0;
171→
172→    for oid_result in revwalk.take(50) {
173→        let oid = match oid_result {
174→            Ok(o) => o,
175→            Err(_) => break,
176→        };
177→        let commit = match repo.find_commit(oid) {
178→            Ok(c) => c,
179→            Err(_) => continue,
180→        };
181→
182→        if let Some(message) = commit.message() {
183→            for line in message.lines() {
184→                if let Some(trailer_id) = line.strip_prefix("Engram-Id: ") {
185→                    if trailer_id.trim() == engram_id_str {
186→                        // Skip if already annotated
187→                        if repo.find_note(Some(ENGRAM_NOTES_REF), oid).is_ok() {
188→                            continue;
189→                        }
190→                        if repo
191→                            .note(&sig, &sig, Some(ENGRAM_NOTES_REF), oid, &note, false)
192→                            .is_ok()
193→                        {
194→                            annotated += 1;
195→                        }
196→                    }
197→                }
198→            }
199→        }
200→    }
201→
202→    if annotated > 0 {
203→        tracing::debug!("session-end: annotated {annotated} commit(s) with engram notes");
204→    }
205→}
206→
207→/// If auto_capture is enabled and no active session exists, discover and import
208→/// the most recent Claude Code session, then create a temporary ActiveSession
209→/// so the prepare-commit-msg handler can inject trailers.
210→fn maybe_auto_capture(storage: &GitStorage, git_dir: &std::path::Path) {
211→    // Don't interfere with an existing session (e.g. from `engram record`)
212→    if ActiveSession::load(git_dir).is_some() {
213→        return;
214→    }
215→
216→    let config = match load_config(storage) {
217→        Some(c) => c,
218→        None => return,
219→    };
220→
221→    if !config.auto_capture {
222→        return;
223→    }
224→
225→    let workdir = match storage.workdir() {
226→        Some(w) => w.to_path_buf(),
227→        None => return,
228→    };
229→
230→    // Discover Claude Code session files for this project
231→    let session_files = match ClaudeCodeImporter::discover_sessions(&workdir) {
232→        Ok(files) => files,
233→        Err(e) => {
234→            tracing::debug!("Auto-capture: failed to discover sessions: {e}");
235→            return;
236→        }
237→    };
238→
239→    if session_files.is_empty() {
240→        tracing::debug!("Auto-capture: no Claude Code sessions found");
241→        return;
242→    }
243→
244→    // Pick the most recently modified session file
245→    let newest = session_files
246→        .into_iter()
247→        .filter_map(|p| {
248→            let mtime = std::fs::metadata(&p).ok()?.modified().ok()?;
249→            Some((p, mtime))
250→        })
251→        .max_by_key(|(_, mtime)| *mtime)
252→        .map(|(p, _)| p);
253→
254→    let session_path = match newest {
255→        Some(p) => p,
256→        None => return,
257→    };
258→
259→    // Import the session
260→    let mut data = match ClaudeCodeImporter::import_session(&session_path) {
261→        Ok(d) => d,
262→        Err(e) => {
263→            tracing::debug!("Auto-capture: failed to import session: {e}");
264→            return;
265→        }
266→    };
267→
268→    // Best-effort LLM summarization
269→    if let Err(e) = summarize_intent(&mut data) {
270→        tracing::debug!("Auto-capture: LLM summarization failed: {e}");
271→    }
272→
273→    // Check for duplicates — if already imported, reuse the existing engram ID
274→    let engram_id = if let Some(existing_id) = data
275→        .manifest
276→        .source_hash
277→        .as_deref()
278→        .and_then(|h| storage.find_by_source_hash(h))
279→    {
280→        // Already imported this exact snapshot — reuse the ID
281→        existing_id
282→    } else {
283→        // New content — store the engram
284→        let id = data.manifest.id.clone();
285→        match storage.create(&data) {
286→            Ok(_) => {
287→                // Best-effort index update
288→                if let Ok(engine) = SearchEngine::open(storage) {
289→                    let _ = engine.index_engram(&data);
290→                }
291→                tracing::debug!("Auto-capture: imported engram {}", &id.as_str()[..8]);
292→                id
293→            }
294→            Err(e) => {
295→                tracing::debug!("Auto-capture: failed to store engram: {e}");
296→                return;
297→            }
298→        }
299→    };
300→
301→    // Create a temporary ActiveSession so the core handler can inject trailers
302→    let agent = data.manifest.agent.clone();
303→    let mut session = ActiveSession::new(
304→        engram_id,
305→        AgentInfo {
306→            name: agent.name,
307→            model: agent.model,
308→            version: agent.version,
309→        },
310→    );
311→    session.token_usage = data.manifest.token_usage.clone();
312→    session.auto_capture = true;
313→
314→    if let Err(e) = session.save(git_dir) {
315→        tracing::debug!("Auto-capture: failed to save session: {e}");
316→    }
317→}
318→
319→/// After post-commit, if the session was auto-created, update the engram
320→/// with the commit SHA and clean up the session file.
321→fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
322→    let session = match ActiveSession::load(git_dir) {
323→        Some(s) if s.auto_capture => s,
324→        _ => return,
325→    };
326→
327→    // The core post-commit handler already recorded the commit SHA in the session.
328→    // Now read back the session to get the commit, update the engram, and clean up.
329→    let updated = ActiveSession::load(git_dir).unwrap_or(session);
330→
331→    if !updated.commits.is_empty() {
332→        // Re-read the engram, update its git_commits, and re-store it
333→        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
334→            for sha in &updated.commits {
335→                if !data.manifest.git_commits.contains(sha) {
336→                    data.manifest.git_commits.push(sha.clone());
337→                }
338→                if !data.lineage.git_commits.contains(sha) {
339→                    data.lineage.git_commits.push(sha.clone());
340→                }
341→            }
342→            // Re-store the updated engram (overwrites the ref)
343→            let _ = storage.create(&data);
344→        }
345→    }
346→
347→    ActiveSession::cleanup(git_dir);
348→    tracing::debug!(
349→        "Auto-capture: finalized engram {} with {} commit(s)",
350→        &updated.engram_id.as_str()[..8],
351→        updated.commits.len()
352→    );
353→}
