403→/// Load EngramConfig from the repo, returning None on any error.
404→fn load_config(storage: &GitStorage) -> Option<EngramConfig> {
405→    let config = storage.repo().config().ok()?;
406→    EngramConfig::load(&config).ok()
407→}
