  1→use engram_core::model::{DeadEnd, Decision};
  2→
  3→/// Best-effort extraction of reasoning insights from raw PTY output.
  4→///
  5→/// This is heuristic: it looks for common phrases that indicate rejected
  6→/// approaches or architectural decisions. Returns empty vecs if no patterns found.
  7→pub fn extract_insights(raw_output: &[u8]) -> ExtractedInsights {
  8→    let text = String::from_utf8_lossy(raw_output);
  9→    let mut dead_ends = Vec::new();
 10→    let mut decisions = Vec::new();
 11→
 12→    for line in text.lines() {
 13→        let trimmed = line.trim();
 14→        if trimmed.is_empty() || trimmed.len() < 10 {
 15→            continue;
 16→        }
 17→        // Skip lines that look like markdown formatting, code, or structured content
 18→        if trimmed.starts_with('#')
 19→            || trimmed.starts_with('|')
 20→            || trimmed.starts_with("```")
 21→            || trimmed.starts_with("- **")
 22→            || trimmed.starts_with("**")
 23→            || trimmed.contains("](")
 24→        {
 25→            continue;
 26→        }
 27→        let lower = trimmed.to_lowercase();
 28→
 29→        // Dead end patterns
 30→        if let Some(de) = try_extract_dead_end(&lower, trimmed) {
 31→            dead_ends.push(de);
 32→        }
 33→
 34→        // Decision patterns
 35→        if let Some(d) = try_extract_decision(&lower, trimmed) {
 36→            decisions.push(d);
 37→        }
 38→    }
 39→
 40→    // Deduplicate by approach/description (sort first so dedup_by catches all)
 41→    dead_ends.sort_by(|a, b| a.approach.cmp(&b.approach));
 42→    dead_ends.dedup_by(|a, b| a.approach == b.approach);
 43→    decisions.sort_by(|a, b| a.description.cmp(&b.description));
 44→    decisions.dedup_by(|a, b| a.description == b.description);
 45→
 46→    ExtractedInsights {
 47→        dead_ends,
 48→        decisions,
 49→    }
 50→}
 51→
 52→pub struct ExtractedInsights {
 53→    pub dead_ends: Vec<DeadEnd>,
 54→    pub decisions: Vec<Decision>,
 55→}
 56→
 57→fn try_extract_dead_end(lower: &str, original: &str) -> Option<DeadEnd> {
 58→    // Pattern: "tried X but Y"
 59→    if let Some(rest) = lower.strip_prefix("tried ") {
 60→        if let Some((approach, reason)) = rest.split_once(" but ") {
 61→            return Some(DeadEnd {
 62→                approach: approach.trim().to_string(),
 63→                reason: reason.trim().to_string(),
 64→            });
 65→        }
 66→    }
 67→
 68→    // Pattern: "rejected X because Y" or "rejected X: Y"
 69→    if let Some(rest) = lower.strip_prefix("rejected ") {
 70→        if let Some((approach, reason)) = rest
 71→            .split_once(" because ")
 72→            .or_else(|| rest.split_once(": "))
 73→        {
 74→            return Some(DeadEnd {
 75→                approach: approach.trim().to_string(),
 76→                reason: reason.trim().to_string(),
 77→            });
 78→        }
 79→    }
 80→
 81→    // Pattern: "X didn't work because Y" (short lines only to avoid matching prose)
 82→    if original.len() < 120 {
 83→        if let Some(pos) = lower.find(" didn't work") {
 84→            let approach = &original[..pos];
 85→            let reason = lower
 86→                .get((pos + " didn't work".len())..)
 87→                .and_then(|r| r.strip_prefix(" because ").or(r.strip_prefix(": ")))
 88→                .unwrap_or("did not work as expected");
 89→            if !approach.is_empty() && approach.len() < 80 {
 90→                return Some(DeadEnd {
 91→                    approach: approach.trim().to_string(),
 92→                    reason: reason.trim().to_string(),
 93→                });
 94→            }
 95→        }
 96→    }
 97→
 98→    // Pattern: "instead of X" (looser, only if line is short enough to be a summary)
 99→    if lower.contains("instead of ") && original.len() < 120 {
100→        if let Some(pos) = lower.find("instead of ") {
101→            let approach = &original[(pos + "instead of ".len())..];
102→            let reason = &original[..pos];
103→            if !approach.is_empty() && approach.len() < 80 && !reason.is_empty() {
104→                return Some(DeadEnd {
105→                    approach: approach.trim().trim_end_matches('.').to_string(),
106→                    reason: reason.trim().to_string(),
107→                });
108→            }
109→        }
110→    }
111→
112→    None
113→}
114→
115→fn try_extract_decision(lower: &str, original: &str) -> Option<Decision> {
116→    // Pattern: "decided to X because Y"
117→    if let Some(rest) = lower.strip_prefix("decided to ") {
118→        if let Some((desc, rationale)) = rest.split_once(" because ") {
119→            return Some(Decision {
120→                description: desc.trim().to_string(),
121→                rationale: rationale.trim().to_string(),
122→            });
123→        }
124→    }
125→
126→    // Pattern: "chose X over Y" (short lines only)
127→    if lower.starts_with("chose ") && original.len() < 120 {
128→        if let Some((desc, _)) = lower
129→            .strip_prefix("chose ")
130→            .and_then(|r| r.split_once(" over "))
131→        {
132→            return Some(Decision {
133→                description: desc.trim().to_string(),
134→                rationale: original.to_string(),
135→            });
136→        }
137→    }
138→
139→    None
140→}
