  1→//! LLM-powered summarization for engram intent fields.
  2→//!
  3→//! When `ANTHROPIC_API_KEY` is set, sends a condensed transcript to Claude
  4→//! to generate high-quality summary, interpreted_goal, dead_ends, and decisions.
  5→//! Falls back silently to existing heuristic-extracted fields if the API key
  6→//! is missing or the call fails.
  7→
  8→use engram_core::model::{
  9→    transcript::TranscriptContent, DeadEnd, Decision, EngramData, FileChangeType,
 10→};
 11→
 12→use crate::error::CaptureError;
 13→
 14→const API_URL: &str = "https://api.anthropic.com/v1/messages";
 15→const API_VERSION: &str = "2023-06-01";
 16→const DEFAULT_MODEL: &str = "claude-haiku-4-5-20251001";
 17→const MAX_PROMPT_CHARS: usize = 50_000;
 18→const MAX_TOKENS: u32 = 2048;
 19→const TIMEOUT_SECS: u64 = 60;
 20→
 21→const SYSTEM_PROMPT: &str = r#"You are analyzing an AI coding session transcript. Extract structured metadata about what happened in this session.
 22→
 23→Respond with ONLY valid JSON (no markdown fencing, no explanation) in this exact format:
 24→{
 25→  "summary": "1-2 sentence summary of what was accomplished in this session",
 26→  "interpreted_goal": "What the AI agent understood the user wanted and the strategy it used to achieve it",
 27→  "dead_ends": [{"approach": "what was tried", "reason": "why it was rejected or didn't work"}],
 28→  "decisions": [{"description": "what was decided", "rationale": "why this choice was made over alternatives"}]
 29→}
 30→
 31→Rules:
 32→- summary: Focus on outcomes, not process. What was built/fixed/changed?
 33→- interpreted_goal: Describe the strategy, not just restate the request. How did the agent plan to solve it?
 34→- dead_ends: Only include approaches that were actually tried and abandoned. Omit if none.
 35→- decisions: Key architectural or design choices with rationale. Omit if none.
 36→- Keep dead_ends and decisions arrays empty [] if there are genuinely none."#;
 37→
 38→/// Enhance intent fields in an EngramData using LLM summarization.
 39→///
 40→/// Checks for API key in this order:
 41→/// 1. `ANTHROPIC_API_KEY` environment variable
 42→/// 2. `anthropic_api_key` in global config (`~/.config/engram/repos.toml`)
 43→///
 44→/// If neither is set or the API call fails, this is a no-op.
 45→/// The existing heuristic-extracted fields are left unchanged in that case.
 46→pub fn summarize_intent(data: &mut EngramData) -> Result<(), CaptureError> {
 47→    // Load global config for fallback API key / model (best-effort)
 48→    let global_config = engram_core::config::GlobalConfig::load().ok();
 49→
 50→    let api_key = match std::env::var("ANTHROPIC_API_KEY") {
 51→        Ok(k) if !k.is_empty() => k,
 52→        _ => match global_config
 53→            .as_ref()
 54→            .and_then(|c| c.settings.anthropic_api_key.clone())
 55→        {
 56→            Some(k) if !k.is_empty() => k,
 57→            _ => {
 58→                tracing::debug!("No API key found (env or config), skipping LLM summarization");
 59→                return Ok(());
 60→            }
 61→        },
 62→    };
 63→
 64→    let model = std::env::var("ENGRAM_SUMMARIZE_MODEL")
 65→        .ok()
 66→        .filter(|s| !s.is_empty())
 67→        .or_else(|| {
 68→            global_config
 69→                .as_ref()
 70→                .and_then(|c| c.settings.summarize_model.clone())
 71→        })
 72→        .unwrap_or_else(|| DEFAULT_MODEL.to_string());
 73→
 74→    let user_message = build_prompt(data);
 75→
 76→    match call_claude(&api_key, &model, &user_message) {
 77→        Ok(response_text) => match parse_response(&response_text) {
 78→            Ok(parsed) => {
 79→                apply_response(data, &parsed);
 80→                tracing::debug!("LLM summarization applied successfully");
 81→                Ok(())
 82→            }
 83→            Err(e) => {
 84→                tracing::warn!("Failed to parse LLM response, keeping heuristic fields: {e}");
 85→                Ok(())
 86→            }
 87→        },
 88→        Err(e) => {
 89→            tracing::warn!("LLM API call failed, keeping heuristic fields: {e}");
 90→            Ok(())
 91→        }
 92→    }
 93→}
 94→
 95→/// Build a condensed transcript prompt for the LLM.
 96→fn build_prompt(data: &EngramData) -> String {
 97→    let mut parts = Vec::new();
 98→
 99→    // Original request
100→    parts.push(format!("## User Request\n{}", data.intent.original_request));
101→
102→    // Condensed transcript
103→    parts.push("\n## Session Transcript".to_string());
104→    for entry in &data.transcript.entries {
105→        let role = match entry.role {
106→            engram_core::model::transcript::Role::User => "USER",
107→            engram_core::model::transcript::Role::Assistant => "ASSISTANT",
108→            engram_core::model::transcript::Role::System => "SYSTEM",
109→            engram_core::model::transcript::Role::Tool => "TOOL",
110→        };
111→
112→        match &entry.content {
113→            TranscriptContent::Text { text } => {
114→                let t = truncate_str(text, 500);
115→                parts.push(format!("[{role}] {t}"));
116→            }
117→            TranscriptContent::ToolUse {
118→                tool_name, input, ..
119→            } => {
120→                // Include tool name and a brief input summary
121→                let input_summary = summarize_json_input(input);
122→                parts.push(format!("[TOOL_USE] {tool_name}: {input_summary}"));
123→            }
124→            TranscriptContent::Thinking { text } => {
125→                let t = truncate_str(text, 300);
126→                parts.push(format!("[THINKING] {t}"));
127→            }
128→            TranscriptContent::ToolResult { .. } => {
129→                // Skip tool results — too verbose, low signal for summarization
130→            }
131→        }
132→    }
133→
134→    // File changes
135→    if !data.operations.file_changes.is_empty() {
136→        parts.push("\n## File Changes".to_string());
137→        for fc in &data.operations.file_changes {
138→            let symbol = match &fc.change_type {
139→                FileChangeType::Created => "+",
140→                FileChangeType::Modified => "~",
141→                FileChangeType::Deleted => "-",
142→                FileChangeType::Renamed { .. } => "->",
143→            };
144→            let mut line = format!("{symbol} {}", fc.path);
145→            if let Some(added) = fc.lines_added {
146→                line.push_str(&format!(" (+{added})"));
147→            }
148→            if let Some(removed) = fc.lines_removed {
149→                line.push_str(&format!(" (-{removed})"));
150→            }
151→            parts.push(line);
152→        }
153→    }
154→
155→    let full = parts.join("\n");
156→    if full.len() > MAX_PROMPT_CHARS {
157→        let mut end = MAX_PROMPT_CHARS;
158→        while end > 0 && !full.is_char_boundary(end) {
159→            end -= 1;
160→        }
161→        full[..end].to_string()
162→    } else {
163→        full
164→    }
165→}
166→
167→/// Truncate a string to max_len chars, appending "..." if truncated.
168→fn truncate_str(s: &str, max_len: usize) -> &str {
169→    if s.len() <= max_len {
170→        s
171→    } else {
172→        // Find a safe char boundary
173→        let mut end = max_len;
174→        while end > 0 && !s.is_char_boundary(end) {
175→            end -= 1;
176→        }
177→        &s[..end]
178→    }
179→}
180→
181→/// Summarize a JSON tool input to a brief string.
182→fn summarize_json_input(input: &serde_json::Value) -> String {
183→    match input {
184→        serde_json::Value::Object(map) => {
185→            let keys: Vec<&String> = map.keys().take(3).collect();
186→            if keys.is_empty() {
187→                "{}".to_string()
188→            } else {
189→                let pairs: Vec<String> = keys
190→                    .iter()
191→                    .map(|k| {
192→                        let v = &map[*k];
193→                        let v_str = match v {
194→                            serde_json::Value::String(s) => truncate_str(s, 60).to_string(),
195→                            _ => {
196→                                let s = v.to_string();
197→                                truncate_str(&s, 60).to_string()
198→                            }
199→                        };
200→                        format!("{k}={v_str}")
201→                    })
202→                    .collect();
203→                pairs.join(", ")
204→            }
205→        }
206→        serde_json::Value::String(s) => truncate_str(s, 100).to_string(),
207→        other => {
208→            let s = other.to_string();
209→            truncate_str(&s, 100).to_string()
210→        }
211→    }
212→}
213→
214→/// Call the Anthropic Messages API.
215→fn call_claude(api_key: &str, model: &str, user_message: &str) -> Result<String, CaptureError> {
216→    let client = reqwest::blocking::Client::builder()
217→        .timeout(std::time::Duration::from_secs(TIMEOUT_SECS))
218→        .build()
219→        .map_err(|e| CaptureError::LlmError(format!("HTTP client error: {e}")))?;
220→
221→    let body = serde_json::json!({
222→        "model": model,
223→        "max_tokens": MAX_TOKENS,
224→        "system": SYSTEM_PROMPT,
225→        "messages": [
226→            { "role": "user", "content": user_message }
227→        ]
228→    });
229→
230→    let response = client
231→        .post(API_URL)
232→        .header("x-api-key", api_key)
233→        .header("anthropic-version", API_VERSION)
234→        .header("content-type", "application/json")
235→        .json(&body)
236→        .send()
237→        .map_err(|e| CaptureError::LlmError(format!("API request failed: {e}")))?;
238→
239→    if !response.status().is_success() {
240→        let status = response.status();
241→        let body_text = response.text().unwrap_or_default();
242→        return Err(CaptureError::LlmError(format!(
243→            "API returned {status}: {body_text}"
244→        )));
245→    }
246→
247→    let resp_json: serde_json::Value = response
248→        .json()
249→        .map_err(|e| CaptureError::LlmError(format!("Failed to parse API response: {e}")))?;
250→
251→    // Extract text from the first content block
252→    resp_json["content"]
253→        .as_array()
254→        .and_then(|arr| arr.first())
255→        .and_then(|block| block["text"].as_str())
256→        .map(|s| s.to_string())
257→        .ok_or_else(|| CaptureError::LlmError("No text in API response".to_string()))
258→}
259→
260→/// Response from LLM summarization.
261→struct SummarizeResponse {
262→    summary: Option<String>,
263→    interpreted_goal: Option<String>,
264→    dead_ends: Vec<DeadEnd>,
265→    decisions: Vec<Decision>,
266→}
267→
268→/// Parse the LLM JSON response into structured fields.
269→fn parse_response(text: &str) -> Result<SummarizeResponse, CaptureError> {
270→    // Strip markdown code fencing if present
271→    let cleaned = text
272→        .trim()
273→        .strip_prefix("```json")
274→        .or_else(|| text.trim().strip_prefix("```"))
275→        .unwrap_or(text.trim());
276→    let cleaned = cleaned.strip_suffix("```").unwrap_or(cleaned).trim();
277→
278→    let json: serde_json::Value = serde_json::from_str(cleaned)
279→        .map_err(|e| CaptureError::LlmError(format!("Invalid JSON from LLM: {e}")))?;
280→
281→    let summary = json["summary"].as_str().map(|s| s.to_string());
282→    let interpreted_goal = json["interpreted_goal"].as_str().map(|s| s.to_string());
283→
284→    let dead_ends = json["dead_ends"]
285→        .as_array()
286→        .map(|arr| {
287→            arr.iter()
288→                .filter_map(|de| {
289→                    Some(DeadEnd {
290→                        approach: de["approach"].as_str()?.to_string(),
291→                        reason: de["reason"].as_str()?.to_string(),
292→                    })
293→                })
294→                .collect()
295→        })
296→        .unwrap_or_default();
297→
298→    let decisions = json["decisions"]
299→        .as_array()
300→        .map(|arr| {
301→            arr.iter()
302→                .filter_map(|d| {
303→                    Some(Decision {
304→                        description: d["description"].as_str()?.to_string(),
305→                        rationale: d["rationale"].as_str()?.to_string(),
306→                    })
307→                })
308→                .collect()
309→        })
310→        .unwrap_or_default();
311→
312→    Ok(SummarizeResponse {
313→        summary,
314→        interpreted_goal,
315→        dead_ends,
316→        decisions,
317→    })
318→}
319→
320→/// Apply LLM-generated fields to the EngramData.
321→fn apply_response(data: &mut EngramData, response: &SummarizeResponse) {
322→    if let Some(summary) = &response.summary {
323→        data.manifest.summary = Some(summary.clone());
324→        data.intent.summary = Some(summary.clone());
325→    }
326→    if let Some(goal) = &response.interpreted_goal {
327→        data.intent.interpreted_goal = Some(goal.clone());
328→    }
329→    if !response.dead_ends.is_empty() {
330→        data.intent.dead_ends = response.dead_ends.clone();
331→    }
332→    if !response.decisions.is_empty() {
333→        data.intent.decisions = response.decisions.clone();
334→    }
335→}
