 19→
 20→pub struct App {
 21→    manifests: Vec<Manifest>,
 22→    detail_cache: Vec<Option<EngramData>>,
 23→    list_state: ListState,
 24→    search_query: String,
 25→    search_mode: bool,
 26→    detail_scroll: u16,
 27→    quit: bool,
 28→    repo_path: std::path::PathBuf,
 29→}
 30→
 31→impl App {
 32→    fn new(manifests: Vec<Manifest>, repo_path: std::path::PathBuf) -> Self {
 33→        let len = manifests.len();
 34→        let mut list_state = ListState::default();
 35→        if len > 0 {
 36→            list_state.select(Some(0));
 37→        }
 38→        Self {
 39→            detail_cache: vec![None; len],
 40→            manifests,
 41→            list_state,
 42→            search_query: String::new(),
 43→            search_mode: false,
 44→            detail_scroll: 0,
 45→            quit: false,
 46→            repo_path,
 47→        }
 48→    }
 49→
 50→    fn selected_index(&self) -> Option<usize> {
 51→        self.list_state.selected()
 52→    }
 53→
 54→    fn move_up(&mut self) {
 55→        if let Some(i) = self.list_state.selected() {
 56→            if i > 0 {
 57→                self.list_state.select(Some(i - 1));
 58→                self.detail_scroll = 0;
 59→            }
 60→        }
 61→    }
 62→
 63→    fn move_down(&mut self) {
 64→        if let Some(i) = self.list_state.selected() {
 65→            if i + 1 < self.manifests.len() {
 66→                self.list_state.select(Some(i + 1));
 67→                self.detail_scroll = 0;
 68→            }
 69→        }
 70→    }
 71→
 72→    fn load_detail(&mut self, index: usize) {
 73→        if self.detail_cache[index].is_some() {
 74→            return;
 75→        }
 76→        if let Ok(storage) = GitStorage::open(&self.repo_path) {
 77→            if let Ok(data) = storage.read(self.manifests[index].id.as_str()) {
 78→                self.detail_cache[index] = Some(data);
 79→            }
 80→        }
 81→    }
 82→
 83→    fn search(&mut self) {
 84→        if self.search_query.is_empty() {
 85→            // Reload all
 86→            if let Ok(storage) = GitStorage::open(&self.repo_path) {
 87→                if let Ok(manifests) = storage.list(&ListOptions::default()) {
 88→                    let len = manifests.len();
 89→                    self.detail_cache = vec![None; len];
 90→                    self.manifests = manifests;
 91→                    if len > 0 {
 92→                        self.list_state.select(Some(0));
 93→                    } else {
 94→                        self.list_state.select(None);
 95→                    }
 96→                }
 97→            }
 98→            return;
 99→        }
100→
101→        if let Ok(storage) = GitStorage::open(&self.repo_path) {
102→            if let Ok(engine) = SearchEngine::open(&storage) {
103→                if let Ok(results) = engine.search(&storage, &self.search_query, 50) {
104→                    let manifests: Vec<_> = results.into_iter().map(|r| r.manifest).collect();
105→                    let len = manifests.len();
106→                    self.detail_cache = vec![None; len];
107→                    self.manifests = manifests;
108→                    if len > 0 {
109→                        self.list_state.select(Some(0));
110→                    } else {
111→                        self.list_state.select(None);
112→                    }
113→                }
114→            }
115→        }
116→    }
117→}
118→
119→pub fn run(repo_path: &Path) -> io::Result<()> {
120→    let storage = GitStorage::open(repo_path).map_err(|e| io::Error::other(e.to_string()))?;
121→
122→    let manifests = storage
123→        .list(&ListOptions::default())
124→        .map_err(|e| io::Error::other(e.to_string()))?;
125→
126→    let mut app = App::new(manifests, repo_path.to_path_buf());
127→
128→    // Setup terminal
129→    enable_raw_mode()?;
130→    io::stdout().execute(EnterAlternateScreen)?;
131→    let backend = CrosstermBackend::new(io::stdout());
132→    let mut terminal = Terminal::new(backend)?;
133→
134→    // Main loop
135→    while !app.quit {
136→        // Eagerly load detail for selected item
137→        if let Some(idx) = app.selected_index() {
138→            app.load_detail(idx);
139→        }
140→
141→        terminal.draw(|f| ui(f, &mut app))?;
142→
143→        if event::poll(std::time::Duration::from_millis(100))? {
144→            if let Event::Key(key) = event::read()? {
145→                if key.kind != KeyEventKind::Press {
146→                    continue;
147→                }
148→
149→                if app.search_mode {
150→                    match key.code {
151→                        KeyCode::Esc => {
152→                            app.search_mode = false;
153→                        }
154→                        KeyCode::Enter => {
155→                            app.search_mode = false;
156→                            app.search();
157→                        }
158→                        KeyCode::Backspace => {
159→                            app.search_query.pop();
160→                        }
161→                        KeyCode::Char(c) => {
162→                            app.search_query.push(c);
163→                        }
164→                        _ => {}
165→                    }
166→                } else {
167→                    match key.code {
168→                        KeyCode::Char('q') => app.quit = true,
169→                        KeyCode::Char('j') | KeyCode::Down => app.move_down(),
170→                        KeyCode::Char('k') | KeyCode::Up => app.move_up(),
171→                        KeyCode::Char('/') => {
172→                            app.search_mode = true;
173→                            app.search_query.clear();
174→                        }
175→                        KeyCode::Char('d') => {
176→                            app.detail_scroll = app.detail_scroll.saturating_add(3);
177→                        }
178→                        KeyCode::Char('u') => {
179→                            app.detail_scroll = app.detail_scroll.saturating_sub(3);
180→                        }
181→                        _ => {}
182→                    }
183→                }
184→            }
185→        }
186→    }
187→
188→    // Restore terminal
189→    disable_raw_mode()?;
190→    io::stdout().execute(LeaveAlternateScreen)?;
191→
192→    Ok(())
193→}
