211→fn render_list(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
212→    let items: Vec<ListItem> = app
213→        .manifests
214→        .iter()
215→        .map(|m| {
216→            let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
217→            let date = m.created_at.format("%m-%d %H:%M");
218→            let summary = m
219→                .summary
220→                .as_deref()
221→                .unwrap_or("(no summary)")
222→                .chars()
223→                .take(40)
224→                .collect::<String>();
225→
226→            ListItem::new(vec![
227→                Line::from(vec![
228→                    Span::styled(format!("{short_id} "), Style::default().fg(Color::Cyan)),
229→                    Span::styled(format!("{date}"), Style::default().fg(Color::DarkGray)),
230→                ]),
231→                Line::from(Span::raw(format!(" {summary}"))),
232→            ])
233→        })
234→        .collect();
235→
236→    let title = if app.search_query.is_empty() {
237→        format!("Engrams ({})", app.manifests.len())
238→    } else {
239→        format!(
240→            "Results for '{}' ({})",
241→            app.search_query,
242→            app.manifests.len()
243→        )
244→    };
245→
246→    let list = List::new(items)
247→        .block(Block::default().borders(Borders::ALL).title(title))
248→        .highlight_style(
249→            Style::default()
250→                .bg(Color::DarkGray)
251→                .add_modifier(Modifier::BOLD),
252→        )
253→        .highlight_symbol("> ");
254→
255→    f.render_stateful_widget(list, area, &mut app.list_state);
256→}
