258→fn render_detail(f: &mut ratatui::Frame, app: &App, area: Rect) {
259→    let Some(idx) = app.selected_index() else {
260→        let empty = Paragraph::new("No engram selected.")
261→            .block(Block::default().borders(Borders::ALL).title("Detail"));
262→        f.render_widget(empty, area);
263→        return;
264→    };
265→
266→    let m = &app.manifests[idx];
267→    let mut lines: Vec<Line> = Vec::new();
268→
269→    // Summary
270→    if let Some(summary) = &m.summary {
271→        lines.push(Line::from(Span::styled(
272→            summary.clone(),
273→            Style::default().add_modifier(Modifier::BOLD),
274→        )));
275→        lines.push(Line::from(""));
276→    }
277→
278→    // Metadata
279→    let model = m.agent.model.as_deref().unwrap_or("unknown");
280→    let cost = m
281→        .token_usage
282→        .effective_cost(m.agent.model.as_deref())
283→        .unwrap_or(0.0);
284→
285→    lines.push(Line::from(vec![
286→        Span::styled("Agent: ", Style::default().fg(Color::DarkGray)),
287→        Span::raw(format!("{} ({})", m.agent.name, model)),
288→    ]));
289→    lines.push(Line::from(vec![
290→        Span::styled("Date:  ", Style::default().fg(Color::DarkGray)),
291→        Span::raw(m.created_at.format("%Y-%m-%d %H:%M:%S").to_string()),
292→    ]));
293→    lines.push(Line::from(vec![
294→        Span::styled("Tokens:", Style::default().fg(Color::DarkGray)),
295→        Span::raw(format!(" {}", m.token_usage.total_tokens)),
296→        Span::styled(" | Cost: ", Style::default().fg(Color::DarkGray)),
297→        Span::styled(format!("${cost:.2}"), Style::default().fg(Color::Green)),
298→    ]));
299→    lines.push(Line::from(vec![
300→        Span::styled("ID:    ", Style::default().fg(Color::DarkGray)),
301→        Span::styled(m.id.as_str().to_string(), Style::default().fg(Color::Cyan)),
302→    ]));
303→
304→    // Full engram data if loaded
305→    if let Some(Some(data)) = app.detail_cache.get(idx) {
306→        lines.push(Line::from(""));
307→
308→        // Intent
309→        lines.push(Line::from(Span::styled(
310→            "Intent",
311→            Style::default()
312→                .fg(Color::Yellow)
313→                .add_modifier(Modifier::BOLD),
314→        )));
315→        lines.push(Line::from(format!(
316→            "  Request: {}",
317→            data.intent.original_request
318→        )));
319→        if let Some(goal) = &data.intent.interpreted_goal {
320→            lines.push(Line::from(format!("  Goal: {goal}")));
321→        }
322→        if let Some(summary) = &data.intent.summary {
323→            lines.push(Line::from(format!("  Summary: {summary}")));
324→        }
325→
326→        // File changes
327→        if !data.operations.file_changes.is_empty() {
328→            lines.push(Line::from(""));
329→            lines.push(Line::from(Span::styled(
330→                "File Changes",
331→                Style::default()
332→                    .fg(Color::Yellow)
333→                    .add_modifier(Modifier::BOLD),
334→            )));
335→            for fc in &data.operations.file_changes {
336→                let (symbol, color) = match &fc.change_type {
337→                    FileChangeType::Created => ("+", Color::Green),
338→                    FileChangeType::Modified => ("~", Color::Yellow),
339→                    FileChangeType::Deleted => ("-", Color::Red),
340→                    FileChangeType::Renamed { .. } => ("R", Color::Blue),
341→                };
342→                lines.push(Line::from(Span::styled(
343→                    format!("  {symbol} {}", fc.path),
344→                    Style::default().fg(color),
345→                )));
346→            }
347→        }
348→
349→        // Dead ends
350→        if !data.intent.dead_ends.is_empty() {
351→            lines.push(Line::from(""));
352→            lines.push(Line::from(Span::styled(
353→                "Dead Ends",
354→                Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
355→            )));
356→            for de in &data.intent.dead_ends {
357→                lines.push(Line::from(format!("  {} - {}", de.approach, de.reason)));
358→            }
359→        }
360→
361→        // Decisions
362→        if !data.intent.decisions.is_empty() {
363→            lines.push(Line::from(""));
364→            lines.push(Line::from(Span::styled(
365→                "Decisions",
366→                Style::default()
367→                    .fg(Color::Blue)
368→                    .add_modifier(Modifier::BOLD),
369→            )));
370→            for d in &data.intent.decisions {
371→                lines.push(Line::from(format!("  {} - {}", d.description, d.rationale)));
372→            }
373→        }
374→    }
375→
376→    let detail = Paragraph::new(lines)
377→        .block(Block::default().borders(Borders::ALL).title("Detail"))
378→        .wrap(Wrap { trim: false })
379→        .scroll((app.detail_scroll, 0));
380→
381→    f.render_widget(detail, area);
382→}
