150→/// Estimate cost from model name and token counts.
151→/// Returns `None` if the model is unrecognized.
152→pub fn estimate_cost(model: Option<&str>, usage: &TokenUsage) -> Option<f64> {
153→    let pricing = lookup_model(model?)?;
154→
155→    // Standard (non-cached) input tokens = input_tokens - cache_read - cache_write
156→    let standard_input = usage
157→        .input_tokens
158→        .saturating_sub(usage.cache_read_tokens)
159→        .saturating_sub(usage.cache_write_tokens);
160→
161→    let cost = (standard_input as f64 * pricing.input_per_million
162→        + usage.output_tokens as f64 * pricing.output_per_million
163→        + usage.cache_read_tokens as f64 * pricing.cache_read_per_million
164→        + usage.cache_write_tokens as f64 * pricing.cache_write_per_million)
165→        / 1_000_000.0;
166→
167→    Some(cost)
168→}
