201→
202→    if annotated > 0 {
203→        tracing::debug!("session-end: annotated {annotated} commit(s) with engram notes");
204→    }
205→}
206→
207→/// If auto_capture is enabled and no active session exists, discover and import
208→/// the most recent Claude Code session, then create a temporary ActiveSession
209→/// so the prepare-commit-msg handler can inject trailers.
210→fn maybe_auto_capture(storage: &GitStorage, git_dir: &std::path::Path) {
211→    // Don't interfere with an existing session (e.g. from `engram record`)
212→    if ActiveSession::load(git_dir).is_some() {
213→        return;
214→    }
215→
216→    let config = match load_config(storage) {
217→        Some(c) => c,
218→        None => return,
219→    };
220→
221→    if !config.auto_capture {
222→        return;
223→    }
224→
225→    let workdir = match storage.workdir() {
226→        Some(w) => w.to_path_buf(),
227→        None => return,
228→    };
229→
230→    // Discover Claude Code session files for this project
231→    let session_files = match ClaudeCodeImporter::discover_sessions(&workdir) {
232→        Ok(files) => files,
233→        Err(e) => {
234→            tracing::debug!("Auto-capture: failed to discover sessions: {e}");
235→            return;
236→        }
237→    };
238→
239→    if session_files.is_empty() {
240→        tracing::debug!("Auto-capture: no Claude Code sessions found");
241→        return;
242→    }
243→
244→    // Pick the most recently modified session file
245→    let newest = session_files
246→        .into_iter()
247→        .filter_map(|p| {
248→            let mtime = std::fs::metadata(&p).ok()?.modified().ok()?;
249→            Some((p, mtime))
250→        })
251→        .max_by_key(|(_, mtime)| *mtime)
252→        .map(|(p, _)| p);
253→
254→    let session_path = match newest {
255→        Some(p) => p,
256→        None => return,
257→    };
258→
259→    // Import the session
260→    let mut data = match ClaudeCodeImporter::import_session(&session_path) {
261→        Ok(d) => d,
262→        Err(e) => {
263→            tracing::debug!("Auto-capture: failed to import session: {e}");
264→            return;
265→        }
266→    };
267→
268→    // Best-effort LLM summarization
269→    if let Err(e) = summarize_intent(&mut data) {
270→        tracing::debug!("Auto-capture: LLM summarization failed: {e}");
271→    }
272→
273→    // Check for duplicates — if already imported, reuse the existing engram ID
274→    let engram_id = if let Some(existing_id) = data
275→        .manifest
276→        .source_hash
277→        .as_deref()
278→        .and_then(|h| storage.find_by_source_hash(h))
279→    {
280→        // Already imported this exact snapshot — reuse the ID
281→        existing_id
282→    } else {
283→        // New content — store the engram
284→        let id = data.manifest.id.clone();
285→        match storage.create(&data) {
286→            Ok(_) => {
287→                // Best-effort index update
288→                if let Ok(engine) = SearchEngine::open(storage) {
289→                    let _ = engine.index_engram(&data);
290→                }
291→                tracing::debug!("Auto-capture: imported engram {}", &id.as_str()[..8]);
292→                id
293→            }
294→            Err(e) => {
295→                tracing::debug!("Auto-capture: failed to store engram: {e}");
296→                return;
297→            }
298→        }
299→    };
300→
301→    // Create a temporary ActiveSession so the core handler can inject trailers
302→    let agent = data.manifest.agent.clone();
303→    let mut session = ActiveSession::new(
304→        engram_id,
305→        AgentInfo {
306→            name: agent.name,
307→            model: agent.model,
308→            version: agent.version,
309→        },
310→    );
311→    session.token_usage = data.manifest.token_usage.clone();
312→    session.auto_capture = true;
313→
314→    if let Err(e) = session.save(git_dir) {
315→        tracing::debug!("Auto-capture: failed to save session: {e}");
316→    }
317→}
318→
319→/// After post-commit, if the session was auto-created, update the engram
320→/// with the commit SHA and clean up the session file.
321→fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
322→    let session = match ActiveSession::load(git_dir) {
323→        Some(s) if s.auto_capture => s,
324→        _ => return,
325→    };
326→
327→    // The core post-commit handler already recorded the commit SHA in the session.
328→    // Now read back the session to get the commit, update the engram, and clean up.
329→    let updated = ActiveSession::load(git_dir).unwrap_or(session);
330→
331→    if !updated.commits.is_empty() {
332→        // Re-read the engram, update its git_commits, and re-store it
333→        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
334→            for sha in &updated.commits {
335→                if !data.manifest.git_commits.contains(sha) {
336→                    data.manifest.git_commits.push(sha.clone());
337→                }
338→                if !data.lineage.git_commits.contains(sha) {
339→                    data.lineage.git_commits.push(sha.clone());
340→                }
341→            }
342→            // Re-store the updated engram (overwrites the ref)
343→            let _ = storage.create(&data);
344→        }
345→    }
346→
347→    ActiveSession::cleanup(git_dir);
348→    tracing::debug!(
349→        "Auto-capture: finalized engram {} with {} commit(s)",
350→        &updated.engram_id.as_str()[..8],
351→        updated.commits.len()
352→    );
353→}
354→
355→/// If push_on_push is enabled, automatically push engram refs alongside code.
356→/// Uses the git CLI instead of libgit2 so it inherits the user's credential helpers.
357→/// Sets ENGRAM_PUSHING=1 to prevent recursive hook invocation.
358→fn maybe_auto_push(storage: &GitStorage) {
359→    // Guard against recursive invocation: our `git push` triggers pre-push again
360→    if std::env::var_os("ENGRAM_PUSHING").is_some() {
361→        return;
362→    }
363→
364→    let config = match load_config(storage) {
365→        Some(c) => c,
366→        None => return,
367→    };
368→
369→    if !config.push_on_push {
370→        return;
371→    }
372→
373→    let workdir = match storage.workdir() {
374→        Some(w) => w.to_path_buf(),
375→        None => return,
376→    };
377→
378→    match std::process::Command::new("git")
379→        .args(["push", "origin", "refs/engrams/*:refs/engrams/*"])
380→        .env("ENGRAM_PUSHING", "1")
381→        .current_dir(&workdir)
382→        .stdout(std::process::Stdio::piped())
383→        .stderr(std::process::Stdio::piped())
384→        .output()
385→    {
386→        Ok(output) if output.status.success() => {
387→            let stderr = String::from_utf8_lossy(&output.stderr);
388→            let pushed = stderr.lines().filter(|l| l.contains("->")).count();
389→            if pushed > 0 {
390→                eprintln!("engram: pushed {pushed} engram ref(s) to origin");
391→            }
392→        }
393→        Ok(output) => {
394→            let stderr = String::from_utf8_lossy(&output.stderr);
395→            tracing::debug!("Auto-push: git push failed: {stderr}");
396→        }
397→        Err(e) => {
398→            tracing::debug!("Auto-push: failed to run git: {e}");
399→        }
400→    }
401→}
