18→pub fn run(args: &PushArgs) -> Result<()> {
19→    let storage = GitStorage::discover().context("Not in a Git repository with engram")?;
20→    let opts = SyncOptions {
21→        dry_run: args.dry_run,
22→        ..Default::default()
23→    };
24→
25→    let result = push_engrams(storage.repo(), &args.remote, &opts)?;
26→
27→    if args.dry_run {
28→        eprintln!(
29→            "Would push {} engram ref(s) to {}",
30→            result.refs_pushed, result.remote
31→        );
32→    } else {
33→        eprintln!(
34→            "Pushed {} engram ref(s) to {}",
35→            result.refs_pushed, result.remote
36→        );
37→    }
38→
39→    Ok(())
40→}
