  6→/// Options for push/fetch operations.
  7→#[derive(Debug, Default)]
  8→pub struct SyncOptions {
  9→    /// Only sync these specific engram ref patterns (empty = all).
 10→    pub refspecs: Vec<String>,
 11→    /// Dry run — don't actually transfer data.
 12→    pub dry_run: bool,
 13→}
 14→
 15→/// Result of a push operation.
 16→#[derive(Debug)]
 17→pub struct PushResult {
 18→    pub remote: String,
 19→    pub refs_pushed: usize,
 20→}
 21→
 22→/// Result of a fetch operation.
 23→#[derive(Debug)]
 24→pub struct FetchResult {
 25→    pub remote: String,
 26→    pub refs_fetched: usize,
 27→}
 28→
 29→/// Push engram refs to a remote.
 30→pub fn push_engrams(
 31→    repo: &Repository,
 32→    remote_name: &str,
 33→    opts: &SyncOptions,
 34→) -> Result<PushResult, ProtocolError> {
 35→    ensure_refspecs(repo, remote_name)?;
 36→
 37→    let refspecs = if opts.refspecs.is_empty() {
 38→        vec![ENGRAM_PUSH_REFSPEC.to_string()]
 39→    } else {
 40→        opts.refspecs.clone()
 41→    };
 42→
 43→    let refs_before = engram_core::storage::refs::list_engram_refs(repo)?;
 44→
 45→    if opts.dry_run {
 46→        // In dry-run, report how many refs exist that would be pushed
 47→        return Ok(PushResult {
 48→            remote: remote_name.into(),
 49→            refs_pushed: refs_before.len(),
 50→        });
 51→    }
 52→
 53→    let mut remote = repo
 54→        .find_remote(remote_name)
 55→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
 56→
 57→    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();
 58→
 59→    remote
 60→        .push(&refspec_strs, None)
 61→        .map_err(|e| ProtocolError::Sync(format!("Push failed: {e}")))?;
 62→
 63→    // Count how many refs were actually pushed (delta)
 64→    let refs_after = engram_core::storage::refs::list_engram_refs(repo)?;
 65→    let new_refs = refs_after.len().saturating_sub(refs_before.len());
 66→    // If no new refs were created locally during push, report the count of refs
 67→    // that existed before (all were pushed/synced)
 68→    let pushed = if new_refs == 0 {
 69→        refs_before.len()
 70→    } else {
 71→        new_refs
 72→    };
 73→
 74→    Ok(PushResult {
 75→        remote: remote_name.into(),
 76→        refs_pushed: pushed,
 77→    })
 78→}
 79→
 80→/// Fetch engram refs from a remote.
 81→///
 82→/// Fetches engram refs from the named remote. In dry-run mode, returns immediately
 83→/// with zero refs fetched.
 84→pub fn fetch_engrams(
 85→    repo: &Repository,
 86→    remote_name: &str,
 87→    opts: &SyncOptions,
 88→) -> Result<FetchResult, ProtocolError> {
 89→    ensure_refspecs(repo, remote_name)?;
 90→
 91→    let refspecs = if opts.refspecs.is_empty() {
 92→        vec![ENGRAM_FETCH_REFSPEC.to_string()]
 93→    } else {
 94→        opts.refspecs.clone()
 95→    };
 96→
 97→    if opts.dry_run {
 98→        return Ok(FetchResult {
 99→            remote: remote_name.into(),
100→            refs_fetched: 0,
101→        });
102→    }
103→
104→    let refs_before = engram_core::storage::refs::list_engram_refs(repo)?;
105→
106→    let mut remote = repo
107→        .find_remote(remote_name)
108→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
109→
110→    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();
111→
112→    remote
113→        .fetch(&refspec_strs, None, None)
114→        .map_err(|e| ProtocolError::Sync(format!("Fetch failed: {e}")))?;
115→
116→    let refs_after = engram_core::storage::refs::list_engram_refs(repo)?;
117→    let new_refs = refs_after.len().saturating_sub(refs_before.len());
118→
119→    Ok(FetchResult {
120→        remote: remote_name.into(),
121→        refs_fetched: new_refs,
122→    })
123→}
