  1→use git2::Repository;
  2→
  3→use crate::error::ProtocolError;
  4→
  5→/// Refspec for fetching engram refs from remotes.
  6→pub const ENGRAM_FETCH_REFSPEC: &str = "+refs/engrams/*:refs/engrams/*";
  7→
  8→/// Refspec for pushing engram refs to remotes.
  9→pub const ENGRAM_PUSH_REFSPEC: &str = "refs/engrams/*:refs/engrams/*";
 10→
 11→/// Refspec for fetching engram notes from remotes.
 12→pub const NOTES_FETCH_REFSPEC: &str = "+refs/notes/engram:refs/notes/engram";
 13→
 14→/// Refspec for pushing engram notes to remotes.
 15→pub const NOTES_PUSH_REFSPEC: &str = "refs/notes/engram:refs/notes/engram";
 16→
 17→/// Ensure the engram refspecs are configured for a remote.
 18→pub fn ensure_refspecs(repo: &Repository, remote_name: &str) -> Result<bool, ProtocolError> {
 19→    let remote = repo
 20→        .find_remote(remote_name)
 21→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
 22→
 23→    let mut needs_fetch = true;
 24→    let mut needs_push = true;
 25→    let mut needs_notes_fetch = true;
 26→    let mut needs_notes_push = true;
 27→
 28→    // Check existing fetch refspecs
 29→    if let Ok(refspecs) = remote.fetch_refspecs() {
 30→        for i in 0..refspecs.len() {
 31→            if let Some(spec) = refspecs.get(i) {
 32→                if spec == ENGRAM_FETCH_REFSPEC {
 33→                    needs_fetch = false;
 34→                }
 35→                if spec == NOTES_FETCH_REFSPEC {
 36→                    needs_notes_fetch = false;
 37→                }
 38→            }
 39→        }
 40→    }
 41→
 42→    // Check existing push refspecs
 43→    if let Ok(refspecs) = remote.push_refspecs() {
 44→        for i in 0..refspecs.len() {
 45→            if let Some(spec) = refspecs.get(i) {
 46→                if spec == ENGRAM_PUSH_REFSPEC {
 47→                    needs_push = false;
 48→                }
 49→                if spec == NOTES_PUSH_REFSPEC {
 50→                    needs_notes_push = false;
 51→                }
 52→            }
 53→        }
 54→    }
 55→
 56→    drop(remote);
 57→
 58→    let mut changed = false;
 59→
 60→    if needs_fetch {
 61→        repo.remote_add_fetch(remote_name, ENGRAM_FETCH_REFSPEC)?;
 62→        changed = true;
 63→    }
 64→    if needs_notes_fetch {
 65→        repo.remote_add_fetch(remote_name, NOTES_FETCH_REFSPEC)?;
 66→        changed = true;
 67→    }
 68→
 69→    if needs_push {
 70→        repo.remote_add_push(remote_name, ENGRAM_PUSH_REFSPEC)?;
 71→        changed = true;
 72→    }
 73→    if needs_notes_push {
 74→        repo.remote_add_push(remote_name, NOTES_PUSH_REFSPEC)?;
 75→        changed = true;
 76→    }
 77→
 78→    Ok(changed)
 79→}
 80→
 81→/// Ensure refspecs for all remotes in the repository.
 82→pub fn ensure_all_refspecs(repo: &Repository) -> Result<Vec<String>, ProtocolError> {
 83→    let remotes = repo.remotes()?;
 84→    let mut configured = Vec::new();
 85→
 86→    for i in 0..remotes.len() {
 87→        if let Some(name) = remotes.get(i) {
 88→            if ensure_refspecs(repo, name)? {
 89→                configured.push(name.to_string());
 90→            }
 91→        }
 92→    }
 93→
 94→    Ok(configured)
 95→}
